def load() -> pd.DataFrame:
    import glob
    import pandas as pd

    paths = sorted(glob.glob('data/legal/input/csn-data-book-2024-csv/CSVs/State MSA Identity Theft data/*.csv'))
    if not paths:
        raise FileNotFoundError('No files matched identity theft glob')

    dfs = []
    for p in paths:
        df = pd.read_csv(p)
        df['__source_file'] = p.split('/')[-1]
        dfs.append(df)
    return pd.concat(dfs, ignore_index=True)

